public class FuelEconomyConverter {

    static final double KM_PER_MILE = 1.609344;
    static final double LITRES_PER_GALLON = 3.785411784;

    public static double kilometresPerLitre(double milesPerGallon) {
        if (milesPerGallon <= 0) {
            return 0.0;
        }
        double kmPerLitre = milesPerGallon * KM_PER_MILE / LITRES_PER_GALLON;
        return Math.round(kmPerLitre * 100.0) / 100.0;
    }

    public static double litresPerHundredKm(double milesPerGallon) {
        if (milesPerGallon <= 0) {
            return 0.0;
        }
        double kmPerLitre = milesPerGallon * KM_PER_MILE / LITRES_PER_GALLON;
        double litres = 100.0 / kmPerLitre;
        return Math.round(litres * 100.0) / 100.0;
    }
}
